// Generates tokens.css (Tailwind v4 @theme + dark mode) and theme.native.json (React Native /
// NativeWind) from tokens.json. `--check` fails when the generated files are out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (file) => fileURLToPath(new URL(file, import.meta.url));
const tokens = JSON.parse(readFileSync(here("./tokens.json"), "utf8"));

function css() {
  const light = Object.entries(tokens.color).map(([name, v]) => `  --color-${name}: ${v.light};`);
  const dark = Object.entries(tokens.color).map(([name, v]) => `    --color-${name}: ${v.dark};`);
  const fonts = Object.entries(tokens.font).map(([name, v]) => `  --font-${name}: ${v};`);
  const radius = Object.entries(tokens.radius).map(([name, v]) => `  --radius-${name}: ${v};`);
  return [
    "/* Generated by packages/tokens/build.mjs — edit tokens.json instead. */",
    "@theme {",
    ...light,
    ...fonts,
    ...radius,
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    ...dark,
    "  }",
    "}",
    "",
  ].join("\n");
}

function native() {
  const pick = (mode) => Object.fromEntries(Object.entries(tokens.color).map(([n, v]) => [n, v[mode]]));
  return JSON.stringify({ light: pick("light"), dark: pick("dark"), font: tokens.font, radius: tokens.radius }, null, 2) + "\n";
}

const outputs = { "./tokens.css": css(), "./theme.native.json": native() };

if (process.argv.includes("--check")) {
  const stale = Object.entries(outputs).filter(([file, text]) => {
    try {
      return readFileSync(here(file), "utf8") !== text;
    } catch {
      return true;
    }
  });
  if (stale.length) {
    console.error(`Out of date: ${stale.map(([f]) => f).join(", ")} — run pnpm --filter @mail-assistant/tokens build`);
    process.exit(1);
  }
} else {
  for (const [file, text] of Object.entries(outputs)) writeFileSync(here(file), text);
}
